-- T4: stated baseboard linear feet drive the baseboard quantities; sqft / 2.5 stays the fallback.
-- These run after the fallbacks (higher priority_order) so the stated feet win.

INSERT OR IGNORE INTO rules (id, name, description, rule_group_id, priority_order, is_active, trigger_mode, condition_json, action_json, created_at, updated_at) VALUES ('cq-baseboard-supplies-lf', 'Baseboard Supplies from Stated Feet', 'Stated baseboard linear feet (fallback: sqft / 2.5)', (SELECT id FROM rule_groups WHERE name = 'Carpentry' LIMIT 1), 45, 1, 'chained', '{"type":"compound","conditions":[{"type":"line_item_exists","productNamePattern":"Materials: Baseboard Supplies","matchMode":"exact"},{"type":"request_text_extract","pattern":"(\\d[\\d,]*)\\s*(?:linear\\s+feet|lin\\.?\\s*ft|\\blf\\b|ft|feet|foot)\\s*(?:of\\s+|in\\s+)?baseboard","variableName":"baseboard_lf"}]}', '[{"type":"compute_quantity","productNamePattern":"Materials: Baseboard Supplies","formula":"baseboard_lf","matchMode":"exact"}]', datetime('now'), datetime('now'));

INSERT OR IGNORE INTO rules (id, name, description, rule_group_id, priority_order, is_active, trigger_mode, condition_json, action_json, created_at, updated_at) VALUES ('cq-baseboard-trim-lf', 'Baseboard Trim Hours from Stated Feet', 'Stated baseboard linear feet / baseboard_rate (fallback: sqft / 2.5 / baseboard_rate)', (SELECT id FROM rule_groups WHERE name = 'Carpentry' LIMIT 1), 60, 1, 'on_create', '{"type":"compound","conditions":[{"type":"line_item_exists","productNamePattern":"Carpentry: Install Baseboard Trim","matchMode":"exact"},{"type":"request_text_extract","pattern":"(\\d[\\d,]*)\\s*(?:linear\\s+feet|lin\\.?\\s*ft|\\blf\\b|ft|feet|foot)\\s*(?:of\\s+|in\\s+)?baseboard","variableName":"baseboard_lf"}]}', '[{"type":"compute_quantity","productNamePattern":"Carpentry: Install Baseboard Trim","formula":"baseboard_lf / baseboard_rate","matchMode":"exact"}]', datetime('now'), datetime('now'));

